//! Configuration constants for the Marabunta Swarm.
//!
//! All timing, sizing, and threshold values live here. These are compile-time
//! defaults; runtime overrides are supported via `SwarmConfig`.

use serde::{Deserialize, Serialize};
use std::path::PathBuf;
use std::time::Duration;

// Build-time compliance profile (generated by build.rs).
// Contains COMPLIANCE_PROFILE_NAME, COMPLIANCE_PROFILE_VERSION,
// COMPLIANCE_PROFILE_DESCRIPTION, and compliance_overrides().
include!(concat!(env!("OUT_DIR"), "/compliance_generated.rs"));

// ============================================================================
// Gossip timing
// ============================================================================

/// How often each node sends gossip messages.
pub const GOSSIP_INTERVAL: Duration = Duration::from_millis(1000);

/// Number of random peers to gossip with per round.
pub const GOSSIP_FANOUT: usize = 3;

/// Minimum fanout regardless of cluster size (floor for dynamic fanout).
pub const GOSSIP_MIN_FANOUT: usize = 3;

/// Jitter range for gossip interval (±percentage). Prevents thundering herd.
pub const GOSSIP_JITTER_PERCENT: u32 = 20;

/// Fraction of gossip fanout directed to same-region peers (0.0 = all random, 1.0 = all same-region).
///
/// When a node has a `geo_region` set, peer selection is biased so that
/// approximately this fraction of gossip targets are in the same region,
/// reducing WAN bandwidth waste in geographically distributed swarms.
/// If the node has no region set, or there are insufficient same-region peers,
/// the remainder is filled from cross-region peers (and vice versa).
pub const GOSSIP_SAME_REGION_RATIO: f32 = 0.7;

// ============================================================================
// Failure detection
// ============================================================================

/// After this silence, a node is marked Suspect.
pub const SUSPECT_THRESHOLD: Duration = Duration::from_secs(10);

/// After this silence, a node is marked Dead and its work is reassigned.
pub const DEAD_THRESHOLD: Duration = Duration::from_secs(30);

/// After this silence, a node is evicted from the knowledge store entirely.
pub const NODE_TIMEOUT: Duration = Duration::from_secs(120);

/// How often the failure detector runs its sweep.
pub const FAILURE_CHECK_INTERVAL: Duration = Duration::from_secs(2);

// ============================================================================
// DNS resolution
// ============================================================================

/// Time-to-live for cached DNS resolution results.
pub const DNS_CACHE_TTL: Duration = Duration::from_secs(60);

// ============================================================================
// Split-brain protection
// ============================================================================

/// Witness reports older than this are discarded during quorum evaluation.
pub const WITNESS_DECAY_SECS: u64 = 60;

/// Fraction of active peers that must agree a node is unreachable before
/// it can be declared dead. Prevents unilateral death declarations during
/// transient network partitions.
pub const QUORUM_FRACTION: f32 = 0.5;

/// Number of consecutive healthy gossip rounds (reachable_fraction >= QUORUM_FRACTION)
/// required before a partition is considered healed and the node resumes normal
/// work claiming.
pub const PARTITION_RECOVERY_ROUNDS: u32 = 2;

/// Maximum number of witness reports to include in a single gossip message.
pub const MAX_WITNESS_REPORTS_PER_MESSAGE: usize = 20;

