pub const MAX_LOAD_THRESHOLD: f32 = 0.8;

/// How often the work loop checks for available chunks to claim.
pub const WORK_CHECK_INTERVAL: Duration = Duration::from_millis(500);

/// Default timeout for chunk execution.
pub const CHUNK_TIMEOUT: Duration = Duration::from_secs(300);

/// Maximum attempts before a chunk is marked permanently failed.
pub const MAX_CHUNK_ATTEMPTS: u32 = 3;

/// Maximum number of chunks a single node can execute concurrently.
pub const MAX_CONCURRENT_CHUNKS: usize = 4;

/// How long to wait after a conflict-resolution loss before reclaiming work.
pub const CONFLICT_BACKOFF: Duration = Duration::from_millis(200);

