// ============================================================================
// Hardware-class-aware trait thresholds
// ============================================================================

use super::traits::HardwareClass;

/// Per-hardware-class thresholds for trait evaluation and concurrency limits.
///
/// Weaker nodes get more lenient thresholds so they can still contribute
/// to the swarm instead of constantly shedding all traits.
pub struct HardwareClassThresholds {
    /// Maximum load at which a node may still claim `CanExecute`.
    pub max_execute_load: f32,
    /// Minimum available RAM (MB) to claim `CanAggregate`.
    pub min_aggregate_ram_mb: u64,
    /// Minimum available disk (MB) to claim `CanStoreState`.
    pub min_store_state_disk_mb: u64,
    /// Maximum number of chunks a single node can execute concurrently.
    pub max_concurrent_chunks: usize,
    /// Maximum load at which a node may still claim `CanStoreState`.
    pub max_store_state_load: f32,
    /// Maximum load at which a node may still claim `CanAggregate`.
    pub max_aggregate_load: f32,
}

/// Thresholds for Minimal-class hardware (< 2 cores or < 2 GB RAM).
///
/// Very lenient: these nodes are old phones, Raspberry Pi Zeros, etc.
/// They should still contribute with a single chunk at a time.
pub const THRESHOLDS_MINIMAL: HardwareClassThresholds = HardwareClassThresholds {
    max_execute_load: 0.95,
    min_aggregate_ram_mb: 128,
    min_store_state_disk_mb: 256,
    max_concurrent_chunks: 1,
    max_store_state_load: 0.8,
    max_aggregate_load: 0.9,
};

/// Thresholds for Light-class hardware (2-4 cores, 2-4 GB RAM).
///
/// Old laptops and budget phones. Slightly more capable than Minimal.
pub const THRESHOLDS_LIGHT: HardwareClassThresholds = HardwareClassThresholds {
    max_execute_load: 0.90,
    min_aggregate_ram_mb: 256,
    min_store_state_disk_mb: 512,
    max_concurrent_chunks: 2,
    max_store_state_load: 0.7,
    max_aggregate_load: 0.8,
};

/// Thresholds for Standard-class hardware (4-8 cores, 4-16 GB RAM).
///
/// Typical desktops and laptops. These match the original hardcoded defaults.
pub const THRESHOLDS_STANDARD: HardwareClassThresholds = HardwareClassThresholds {
    max_execute_load: 0.80,
    min_aggregate_ram_mb: 512,
    min_store_state_disk_mb: 1024,
    max_concurrent_chunks: 4,
    max_store_state_load: 0.6,
    max_aggregate_load: 0.7,
};

/// Thresholds for Heavy-class hardware (8+ cores, 16+ GB RAM).
///
/// Workstations and servers. Same thresholds as Standard but higher concurrency.
pub const THRESHOLDS_HEAVY: HardwareClassThresholds = HardwareClassThresholds {
    max_execute_load: 0.80,
    min_aggregate_ram_mb: 512,
    min_store_state_disk_mb: 1024,
    max_concurrent_chunks: 8,
    max_store_state_load: 0.6,
    max_aggregate_load: 0.7,
};

/// Look up the thresholds for a given hardware class.
pub fn thresholds_for_class(class: HardwareClass) -> &'static HardwareClassThresholds {
    match class {
        HardwareClass::Minimal => &THRESHOLDS_MINIMAL,
        HardwareClass::Light => &THRESHOLDS_LIGHT,
        HardwareClass::Standard => &THRESHOLDS_STANDARD,
        HardwareClass::Heavy => &THRESHOLDS_HEAVY,
    }
}

