// ============================================================================
// Sub-configuration structs (promoted from constants)
// ============================================================================

/// Admission subsystem configuration.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AdmissionConfig {
    #[serde(default = "default_jury_min_size")]
    pub jury_min_size: usize,
    #[serde(default = "default_jury_max_size")]
    pub jury_max_size: usize,
    #[serde(default = "default_probation_min_tasks")]
    pub probation_min_tasks: u32,
    #[serde(default = "default_probation_max_tasks")]
    pub probation_max_tasks: u32,
    #[serde(default = "default_admission_test_timeout", with = "humantime_serde")]
    pub test_timeout: Duration,
    #[serde(default = "default_admission_verdict_timeout", with = "humantime_serde")]
    pub verdict_timeout: Duration,
    #[serde(default = "default_admission_failure_threshold")]
    pub failure_threshold: f32,
    #[serde(default = "default_juror_penalty")]
    pub juror_penalty: f32,
    #[serde(default = "default_juror_bonus")]
    pub juror_bonus: f32,
    #[serde(default = "default_admission_check_interval", with = "humantime_serde")]
    pub check_interval: Duration,
    #[serde(default = "default_graduation_success_rate")]
    pub graduation_success_rate: f32,
    #[serde(default = "default_rate_limit_max_requests")]
    pub rate_limit_max_requests: u32,
    #[serde(default = "default_rate_limit_window", with = "humantime_serde")]
    pub rate_limit_window: Duration,
    #[serde(default = "default_nonce_cache_size")]
    pub nonce_cache_size: usize,
    #[serde(default = "default_cpu_hash_iterations")]
    pub cpu_hash_iterations_per_core: u64,
}

impl Default for AdmissionConfig {
    fn default() -> Self {
        Self {
            jury_min_size: super::admission::JURY_MIN_SIZE,
            jury_max_size: super::admission::JURY_MAX_SIZE,
            probation_min_tasks: super::admission::PROBATION_MIN_TASKS,
            probation_max_tasks: super::admission::PROBATION_MAX_TASKS,
            test_timeout: super::admission::TEST_TIMEOUT,
            verdict_timeout: super::admission::VERDICT_TIMEOUT,
            failure_threshold: super::admission::FAILURE_THRESHOLD,
            juror_penalty: super::admission::JUROR_PENALTY,
            juror_bonus: super::admission::JUROR_BONUS,
            check_interval: super::admission::ADMISSION_CHECK_INTERVAL,
            graduation_success_rate: super::admission::GRADUATION_SUCCESS_RATE,
            rate_limit_max_requests: super::admission::RATE_LIMIT_MAX_REQUESTS,
            rate_limit_window: super::admission::RATE_LIMIT_WINDOW,
            nonce_cache_size: super::admission::NONCE_CACHE_SIZE,
            cpu_hash_iterations_per_core: super::admission::CPU_HASH_ITERATIONS_PER_CORE,
        }
    }
}

fn default_jury_min_size() -> usize { super::admission::JURY_MIN_SIZE }
fn default_jury_max_size() -> usize { super::admission::JURY_MAX_SIZE }
fn default_probation_min_tasks() -> u32 { super::admission::PROBATION_MIN_TASKS }
fn default_probation_max_tasks() -> u32 { super::admission::PROBATION_MAX_TASKS }
fn default_admission_test_timeout() -> Duration { super::admission::TEST_TIMEOUT }
fn default_admission_verdict_timeout() -> Duration { super::admission::VERDICT_TIMEOUT }
fn default_admission_failure_threshold() -> f32 { super::admission::FAILURE_THRESHOLD }
