/// Full swarm configuration, overridable at runtime via config file or env.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SwarmConfig {
    /// This node's listen address (e.g., "0.0.0.0:4200")
    pub listen_addr: String,

    /// Bootstrap/seed server addresses
    pub bootstrap_servers: Vec<String>,

    /// Gossip interval override
    #[serde(with = "humantime_serde")]
    pub gossip_interval: Duration,

    /// Gossip fanout override
    pub gossip_fanout: usize,

    /// Failure detection: suspect threshold
    #[serde(with = "humantime_serde")]
    pub suspect_threshold: Duration,

    /// Failure detection: dead threshold
    #[serde(with = "humantime_serde")]
    pub dead_threshold: Duration,

    /// Maximum concurrent chunk executions
    pub max_concurrent_chunks: usize,

    /// Maximum load threshold
    pub max_load: f32,

    /// Chunk execution timeout
    #[serde(with = "humantime_serde")]
    pub chunk_timeout: Duration,

    /// Path to persist node identity (NodeId + generation)
    pub identity_file: Option<String>,

    /// Path to persist swarm state (for can_store_state nodes)
    pub state_dir: Option<String>,

    /// Traits to force-enable regardless of resource evaluation
    #[serde(default)]
    pub force_traits: Vec<String>,

    /// Traits to force-disable regardless of resource evaluation
    #[serde(default)]
    pub deny_traits: Vec<String>,

    /// Node type hint (e.g., "bare-metal", "cloud-vm", "mobile", "raspberry-pi")
    #[serde(default)]
    pub node_type: Option<String>,

    /// Maximum number of collectives this node may join
    #[serde(default = "default_max_collectives")]
    pub max_collectives: usize,

    /// Bidding window duration for marketplace postings
    #[serde(default = "default_bid_window", with = "humantime_serde")]
    pub bid_window: Duration,

    /// Minimum capability match score to be eligible for a posting
    #[serde(default = "default_min_capability_match")]
    pub min_capability_match: f32,

    /// Number of recent jobs in the rolling reputation window
    #[serde(default = "default_reputation_window_size")]
    pub reputation_window_size: usize,

    /// Override for the energy cost weight in marketplace scoring.
    /// When set, replaces the compile-time `SCORING_WEIGHT_ENERGY` constant.
    #[serde(default)]
    pub scoring_weight_energy: Option<f64>,

    /// Plugin host configuration (optional — no plugins loaded if absent).
    #[serde(default)]
    pub plugin_host: Option<crate::plugin::config::PluginHostConfig>,

    /// Whether API authentication is required (default true).
    ///
    /// When `false`, all routes are accessible without a bearer token.
    /// Useful for local development and testing.
    #[serde(default = "default_api_auth_required")]
    pub api_auth_required: bool,

    /// Path to a file where the initial admin token is written on first run.
    ///
    /// If the file does not exist when the node starts, a fresh admin token
    /// is generated and written here. If the file already exists, no new
    /// token is generated.
    #[serde(default)]
    pub admin_token_file: Option<PathBuf>,

    /// Pre-configured data residency policies loaded from config file.
    /// These are merged into the node's PolicySet on startup.
    #[serde(default)]
    pub data_residency_policies: Vec<super::policy::DataResidencyPolicy>,

    /// Whether auto-update is enabled (default: false, opt-in).
    #[serde(default)]
    pub auto_update: bool,

    /// URL of the update server to check for new versions.
    /// The manifest is fetched from `{update_url}/latest.json`.
    #[serde(default)]
    pub update_url: Option<String>,

    /// Whether to enable the PostgreSQL wire protocol (PgWire) on port 5432.
    #[serde(default)]
    pub enable_pgwire: bool,

    /// Whether to enable the Amazon S3-compatible Proxy Gateway on port 9000.
    #[serde(default)]
    pub enable_s3_gateway: bool,

    /// Whether to enable the Planetary Redis protocol (RESP) on port 6379.
    #[serde(default)]
    pub enable_redis: bool,

    /// How often to check for updates (default: 6 hours).
    #[serde(default = "default_update_check_interval", with = "humantime_serde")]
    pub update_check_interval: Duration,

    /// Ed25519 public key (base64-encoded) for verifying release signatures.
    #[serde(default)]
    pub update_signing_key: Option<String>,

    // === Management layer fields ===

    /// Human-readable swarm name.
    #[serde(default = "default_swarm_name")]
    pub swarm_name: String,

    /// Swarm description.
    #[serde(default)]
    pub swarm_description: String,

    /// Path to swarm identity keypair file (auto-generated if absent).
    #[serde(default)]
    pub swarm_identity_file: Option<String>,

    /// Path to management UI static files directory (None = disabled).
    #[serde(default)]
    pub management_ui_dir: Option<String>,

    /// Path to custom archetypes TOML file (None = builtins only).
    #[serde(default)]
    pub archetypes_file: Option<String>,

    /// Path to custom visions TOML file (None = builtins only).
    #[serde(default)]
    pub visions_file: Option<String>,

    /// Path to alert rules file (None = builtin rules only).
    #[serde(default)]
    pub alert_rules_file: Option<String>,

    /// Path to SLA definitions file (None = default SLAs only).
    #[serde(default)]
    pub sla_definitions_file: Option<String>,

    /// Path to audit log persistence file (None = in-memory only).
    #[serde(default)]
    pub audit_log_file: Option<String>,

    /// Whether to enable the management layer subsystems.
    #[serde(default = "default_enable_management_layer")]
    pub enable_management_layer: bool,

    /// Whether to enable the Neuromancer intelligence/security_domain subsystem.
    #[serde(default)]
    pub enable_neuromancer: bool,

    /// Neuromancer subsystem configuration (optional; defaults used when None).
    #[serde(default)]
    pub neuromancer: Option<super::neuromancer::config::NeuromancerConfig>,

    /// Whether to enable the swarm-managed PostgreSQL subsystem.
    ///
    /// When true (the default for non-minimal deployments), the swarm
    /// automatically deploys and manages PostgreSQL on capable nodes
    /// (≥4 GB RAM, ≥2 GB disk). Provides the backing store for config
    /// history, time-travel queries, audit trails, and compliance records.
    #[serde(default = "default_enable_postgres")]
    pub enable_postgres: bool,

    /// PostgreSQL subsystem configuration (optional; defaults used when None).
    #[serde(default)]
    pub postgres: Option<super::postgres::config::PgConfig>,

    // === Sub-configuration structs (promoted from constants) ===

    /// Admission subsystem tuning.
    #[serde(default)]
    pub admission: AdmissionConfig,

    /// Transport tuning.
    #[serde(default)]
    pub transport_tuning: TransportTuningConfig,

    /// Gossip tuning.
    #[serde(default)]
    pub gossip_tuning: GossipTuningConfig,

    /// Trait evaluation tuning.
    #[serde(default)]
    pub trait_eval: TraitEvalConfig,

    /// Work distribution tuning.
    #[serde(default)]
    pub work_tuning: WorkTuningConfig,

    /// Whether the Observe-and-Interfere subsystem is enabled.
    #[serde(default)]
    pub enable_observe_and_interfere: bool,

    /// OAI configuration (only used when enable_observe_and_interfere is true).
    #[serde(default)]
    pub observe_and_interfere: Option<super::observe::config::OaiConfig>,

    // === EU Highestsec Compliance fields ===

    /// Whether Software-Only Blind Computing (FHE + ZKP) is enabled.
    #[serde(default)]
    pub enable_blind_computation: bool,

    /// Whether highestsec zone enforcement is enabled.
    #[serde(default)]
    pub enable_highestsec_zones: bool,

    /// Highestsec zone configuration (only used when enable_highestsec_zones is true).
    #[serde(default)]
    pub highestsec_zone: Option<HighestsecZoneConfig>,

    /// Whether to accept unsigned gossip messages (migration mode).
    /// Default: false (unsigned gossip is rejected).
    #[serde(default)]
    pub allow_unsigned_gossip: bool,

    /// TLS certificate PEM file path.
    #[serde(default)]
    pub tls_cert_path: Option<String>,

    /// TLS private key PEM file path.
    #[serde(default)]
    pub tls_key_path: Option<String>,

    /// Allow plaintext transport (development/testing only).
    /// Default: false.
    #[serde(default)]
    pub allow_plaintext: bool,

    /// Auto-generate self-signed TLS certificates for dev mode.
    #[serde(default = "default_true")]
    pub auto_generate_tls: bool,

    /// WebSocket control plane authentication token.
    /// If not set, a cryptographically random token is generated at startup.
    /// Must be at least 16 characters if explicitly set.
    #[serde(default)]
    pub websocket_auth_token: Option<String>,

    /// Whether GDPR right-to-erasure engine is enabled.
    /// Default: true (GDPR should be on by default for EU compliance).
    #[serde(default = "default_true")]
    pub enable_gdpr: bool,

    /// Whether the Phantom protocol (cover traffic) is enabled.
    #[serde(default)]
    pub enable_phantom_protocol: bool,

    /// GDPR engine configuration (only used when enable_gdpr is true).
    #[serde(default)]
    pub gdpr: Option<super::gdpr::GdprConfig>,
}

