impl SwarmConfig {
    /// Validate configuration consistency. Returns an error message if invalid.
    pub fn validate(&self) -> Result<(), String> {
        // Enforce TLS when blind computation or highestsec zones are enabled
        if (self.enable_blind_computation || self.enable_highestsec_zones) && self.allow_plaintext {
            return Err(
                "allow_plaintext must be false when blind computation or highestsec zones are enabled"
                    .into(),
            );
        }
        // Reject unsigned gossip when blind computation is enabled
        if self.enable_blind_computation && self.allow_unsigned_gossip {
            return Err(
                "allow_unsigned_gossip must be false when blind computation is enabled. \
                 Unsigned gossip allows message forgery which undermines blind computation trust."
                    .into(),
            );
        }
        // Blind computation requires highestsec zones for zone enforcement
        if self.enable_blind_computation && !self.enable_highestsec_zones {
            return Err(
                "enable_highestsec_zones must be true when blind computation is enabled. \
                 Blind computation requires mandatory zone ID enforcement."
                    .into(),
            );
        }
        // Blind computation requires neuromancer for incident response
        if self.enable_blind_computation && !self.enable_neuromancer {
            return Err(
                "enable_neuromancer must be true when blind computation is enabled. \
                 Blind computation workloads require anomaly detection and incident response."
                    .into(),
            );
        }
        // Validate websocket auth token if provided
        if let Some(ref token) = self.websocket_auth_token {
            if token.len() < 16 {
                return Err("websocket_auth_token must be at least 16 characters".into());
            }
            const WEAK_TOKENS: &[&str] = &[
                "default-token",
                "password",
                "admin",
                "secret",
                "changeme",
                "test-token",
                "your-secure-token-here",
            ];
            if WEAK_TOKENS.contains(&token.as_str()) {
                return Err(format!(
                    "websocket_auth_token is a known weak value: '{token}'"
                ));
            }
        }
        Ok(())
    }
}

