// ============================================================================
// Timestamp trust & drift quarantine (Hardening A.1)
// ============================================================================

/// Maximum acceptable clock drift before clamping.
/// Timestamps within this window are silently clamped to `now + MAX_ACCEPTABLE_DRIFT`.
pub const MAX_ACCEPTABLE_DRIFT: Duration = Duration::from_secs(5);

/// Drift beyond this threshold causes the entire gossip message to be rejected.
pub const DRIFT_REJECT_THRESHOLD: Duration = Duration::from_secs(30);

/// Number of drift violations within the quarantine window before auto-quarantine.
pub const ANOMALY_QUARANTINE_THRESHOLD: u32 = 10;

/// Sliding window for counting drift violations.
pub const ANOMALY_QUARANTINE_WINDOW: Duration = Duration::from_secs(60);

// ============================================================================
// Additional message bounds (Hardening A.8)
// ============================================================================

/// Maximum software inventory entries per gossip message.
pub const MAX_SOFTWARE_INVENTORIES_PER_MESSAGE: usize = 50;

// ============================================================================
// Scrutiny & Witness Configuration (Audit W1A)
// ============================================================================
//
// These constants govern the adaptive scrutiny model introduced in W1A.
// They are distinct from the existing WITNESS_DECAY_SECS and
// MAX_WITNESS_REPORTS_PER_MESSAGE constants, which serve the *failure
// detection* subsystem. Both systems coexist.

/// Witness response timeout for Low-criticality actions (seconds).
/// Low actions require no witnesses, so the timeout is zero.
pub const SCRUTINY_WITNESS_TIMEOUT_LOW: u64 = 0;

/// Witness response timeout for Normal-criticality actions (seconds).
pub const SCRUTINY_WITNESS_TIMEOUT_NORMAL: u64 = 5;

/// Witness response timeout for High-criticality actions (seconds).
pub const SCRUTINY_WITNESS_TIMEOUT_HIGH: u64 = 10;

/// Witness response timeout for Critical-criticality actions (seconds).
pub const SCRUTINY_WITNESS_TIMEOUT_CRITICAL: u64 = 30;

/// Witness response timeout for Emergency-criticality actions (seconds).
pub const SCRUTINY_WITNESS_TIMEOUT_EMERGENCY: u64 = 60;

/// Minimum distinct network segments for High-tier witnesses.
pub const MIN_WITNESS_SEGMENTS_HIGH: usize = 2;

/// Minimum distinct network segments for Critical-tier witnesses.
pub const MIN_WITNESS_SEGMENTS_CRITICAL: usize = 3;

/// Required witnesses for Normal-tier actions.
pub const WITNESS_COUNT_NORMAL: usize = 2;

/// Required witnesses for High-tier actions.
pub const WITNESS_COUNT_HIGH: usize = 5;

/// Minimum witnesses for Critical-tier actions.
pub const WITNESS_COUNT_CRITICAL: usize = 7;

/// How often the scrutiny engine re-evaluates action-type mappings
/// against configuration changes (seconds).
pub const SCRUTINY_RESCAN_INTERVAL_SECS: u64 = 300;

// ============================================================================
// Workflow Lock Configuration (W3A)
// ============================================================================

/// TTL for workflow instance distributed locks (seconds).
pub const WF_LOCK_TTL_SECS: u32 = 30;

/// Delay between lock acquisition retry attempts (milliseconds).
pub const WF_LOCK_RETRY_MS: u64 = 100;

/// Maximum number of lock acquisition retries before giving up.
pub const WF_LOCK_MAX_RETRIES: u32 = 50;

/// TTL for partial approval entries (seconds). Default 1 hour.
pub const WF_APPROVAL_TTL_SECS: u64 = 3600;

// ============================================================================
// Timer Service Configuration (W3C)
// ============================================================================

/// How often the timer polling loop checks for expired timers (seconds).
pub const TIMER_CHECK_INTERVAL_SECS: u64 = 10;

// ============================================================================
// Witness Consensus Protocol (W3D)
// ============================================================================

/// Quorum ratio for Normal-tier witnesses (all 2 must confirm).
pub const WITNESS_QUORUM_RATIO_NORMAL: f64 = 1.0;

/// Quorum ratio for High-tier witnesses (supermajority: 4 of 5).
pub const WITNESS_QUORUM_RATIO_HIGH: f64 = 0.8;

/// Quorum ratio for Critical-tier witnesses (supermajority: 5 of 7).
pub const WITNESS_QUORUM_RATIO_CRITICAL: f64 = 0.72;

/// Background signature re-verification interval (seconds).
pub const WITNESS_BG_VERIFY_INTERVAL_SECS: u64 = 120;

/// Maximum concurrent in-flight witness rounds.
pub const WITNESS_MAX_CONCURRENT_ROUNDS: usize = 16;

/// Delay before retrying a failed witness request (milliseconds).
pub const WITNESS_RETRY_DELAY_MS: u64 = 500;

/// Timeout for audit trail reconstruction sync requests (seconds).
pub const AUDIT_SYNC_TIMEOUT_SECS: u64 = 10;

/// Returns the witness requirements for a given criticality level.
///
/// Returns `(witness_count, min_segments)`:
/// - Low:       (0, 0)        -- no witnesses needed
/// - Normal:    (2, 1)        -- 2 witnesses, any segment
/// - High:      (5, 2)        -- 5 witnesses, 2+ segments
/// - Critical:  (7, 3)        -- 7+ witnesses, 3+ segments
/// - Emergency: (MAX, MAX)    -- all reachable nodes, all segments
pub fn witness_requirements(level: &super::types::CriticalityLevel) -> (usize, usize) {
    use super::types::CriticalityLevel;
    match level {
        CriticalityLevel::Low       => (0, 0),
        CriticalityLevel::Normal    => (WITNESS_COUNT_NORMAL, 1),
        CriticalityLevel::High      => (WITNESS_COUNT_HIGH, MIN_WITNESS_SEGMENTS_HIGH),
        CriticalityLevel::Critical  => (WITNESS_COUNT_CRITICAL, MIN_WITNESS_SEGMENTS_CRITICAL),
        CriticalityLevel::Emergency => (usize::MAX, usize::MAX),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_config_rejects_blind_with_seccomp_log_only() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.allow_plaintext = false;
        config.seccomp = Some(crate::highestsec::seccomp::SeccompConfig {
            enabled: true,
            log_only: true,
            additional_allowed: vec![],
        });
        assert!(config.validate().is_err());
    }

    #[test]
    fn test_config_accepts_blind_with_seccomp_enforce() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.enable_highestsec_zones = true;
        config.enable_neuromancer = true;
        config.allow_plaintext = false;
        config.seccomp = Some(crate::highestsec::seccomp::SeccompConfig {
            enabled: true,
            log_only: false,
            additional_allowed: vec![],
        });
        assert!(config.validate().is_ok());
    }

    #[test]
    fn test_config_rejects_blind_without_highestsec_zones() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.enable_highestsec_zones = false;
        config.allow_plaintext = false;
        config.seccomp = Some(crate::highestsec::seccomp::SeccompConfig {
            enabled: true,
            log_only: false,
            additional_allowed: vec![],
        });
        let err = config.validate().unwrap_err();
        assert!(
            err.contains("enable_highestsec_zones must be true"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn test_config_blind_no_seccomp_field_rejected() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.allow_plaintext = false;
        // seccomp is None — must be rejected now (FIX P2-10)
        let err = config.validate().unwrap_err();
        assert!(
            err.contains("seccomp configuration must be provided"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn test_config_rejects_blind_with_unsigned_gossip() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.allow_plaintext = false;
        config.allow_unsigned_gossip = true;
        config.seccomp = Some(crate::highestsec::seccomp::SeccompConfig {
            enabled: true,
            log_only: false,
            additional_allowed: vec![],
        });
        let err = config.validate().unwrap_err();
        assert!(
            err.contains("allow_unsigned_gossip must be false"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn test_config_rejects_blind_without_neuromancer() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.enable_highestsec_zones = true;
        config.enable_neuromancer = false;
        config.allow_plaintext = false;
        config.seccomp = Some(crate::highestsec::seccomp::SeccompConfig {
            enabled: true,
            log_only: false,
            additional_allowed: vec![],
        });
        let err = config.validate().unwrap_err();
        assert!(
            err.contains("enable_neuromancer must be true"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn test_config_rejects_blind_with_forbidden_additional_allowed() {
        let mut config = SwarmConfig::default();
        config.enable_blind_execution = true;
        config.enable_highestsec_zones = true;
        config.enable_neuromancer = true;
        config.allow_plaintext = false;
        config.seccomp = Some(crate::highestsec::seccomp::SeccompConfig {
            enabled: true,
            log_only: false,
            additional_allowed: vec!["socket".to_string()],
        });
        let err = config.validate().unwrap_err();
        assert!(
            err.contains("blind computation forbids 'socket'"),
            "unexpected error: {err}"
        );
    }

    #[test]
    fn test_default_blind_trust_fields() {
        let config = SwarmConfig::default();
        assert!((config.blind_min_trust_score - 0.8).abs() < f64::EPSILON);
        assert_eq!(config.blind_min_verified_jobs, 50);
    }
}


